    /// <summary>语言包对应的一份：英文的语言包用 EnUs，其余用 ZhCn。</summary>
    /// <param name="lang">所在的语言包。</param>
    public static PatternsMessages For(Lang lang) => lang.Code.StartsWith("en", StringComparison.OrdinalIgnoreCase) ? EnUs : ZhCn;
